import { defineConfig } from '@playwright/test';
import { readFileSync } from 'node:fs';

// Generated by `supabase status -o json`; contains local-only test credentials, never committed.
const local = JSON.parse(readFileSync('supabase/.temp/local-status.json','utf8'));
const apiUrl = local.API_URL;
if(new URL(apiUrl).hostname!=='127.0.0.1')throw new Error('Integration tests may only run against the local Supabase stack.');

export default defineConfig({
  testDir:'./tests',testMatch:'**/supabase.spec.ts',workers:1,
  use:{baseURL:'http://127.0.0.1:3101',launchOptions:{executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium'},trace:'retain-on-failure'},
  webServer:{
    command:'npm run dev -- --port 3101',url:'http://127.0.0.1:3101',reuseExistingServer:false,
    env:{NEXT_PUBLIC_DEMO_MODE:'false',NEXT_PUBLIC_SUPABASE_URL:apiUrl,NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY:local.ANON_KEY},
    timeout:120_000,
  },
});
